"""Date ranges. A range runs from a start date to an end date, and both days count."""

from __future__ import annotations

from datetime import date, timedelta


def is_weekend(day: date) -> bool:
    """Whether day is a Saturday or a Sunday."""
    return day.weekday() >= 5


class DateRange:
    """A start date and an end date; both days count."""

    def __init__(self, start: date, end: date) -> None:
        self.start = start
        self.end = end

    def length(self) -> int:
        """Number of days in the range."""
        return (self.end - self.start).days + 1

    def contains(self, day: date) -> bool:
        """Whether day falls inside the range."""
        return self.start <= day <= self.end

    def overlap_days(self, other: DateRange) -> int:
        """Number of days shared with other, or 0 when they do not meet."""
        first, last = max(self.start, other.start), min(self.end, other.end)
        return max(0, (last - first).days + 1)


def length(start: date, end: date) -> int:
    """Number of days in the range."""
    return DateRange(start, end).length()


def contains(start: date, end: date, day: date) -> bool:
    """Whether day falls inside the range."""
    return DateRange(start, end).contains(day)


def overlap_days(a_start: date, a_end: date, b_start: date, b_end: date) -> int:
    """Number of days that two ranges share, or 0 when they do not meet."""
    return DateRange(a_start, a_end).overlap_days(DateRange(b_start, b_end))


def count_days(start: date, end: date, weekend: bool = False) -> int:
    """Number of weekend days (weekend=True) or weekdays in the range."""
    count = 0
    day = start
    while day <= end:
        if (day.weekday() >= 5) == weekend:
            count += 1
        day += timedelta(days=1)
    return count


def weekdays(start: date, end: date) -> int:
    """Number of Mondays to Fridays in the range."""
    return count_days(start, end)


def weekend_days(start: date, end: date) -> int:
    """Number of Saturdays and Sundays in the range."""
    return count_days(start, end, weekend=True)

