"""Reading and writing date ranges as text."""

from __future__ import annotations

from datetime import date


def parse_range(text: str) -> tuple[date, date]:
    """Parse "YYYY-MM-DD..YYYY-MM-DD" into (start, end)."""
    first, last = text.split("..")
    return date.fromisoformat(first.strip()), date.fromisoformat(last.strip())


def format_day(day: date) -> str:
    """A date for people, for example "5 Mar 2024"."""
    return f"{day.day} {day:%b %Y}"


def format_range(start: date, end: date) -> str:
    """A range for people, for example "1 Mar 2024 to 5 Mar 2024"."""
    return f"{format_day(start)} to {format_day(end)}"

